---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Invite to collaborate: Add teammates by email as chips, set their role, send.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change invite-to-collaborate.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './invite-to-collaborate.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="invite" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ivx panel">
  <div class="ivx-h"><b>Invite to Pricing refresh</b><span class="muted">They can see frames, the brief and agent runs</span></div>
  <div class="ivx-f"><div class="ivx-chips"></div><input placeholder="name@studio.com" aria-label="Email addresses" spellcheck="false"><button class="ivx-role" data-pop=".ivx-rp" data-pop-align="end"><span>Can edit</span><svg class="i xs"><use href="#i-chev-d"/></svg></button></div>
  <div class="pop ivx-rp" role="menu"><button class="mi" role="menuitemradio" data-close data-r="Can edit" aria-checked="true"><span>Can edit<span class="d">Change frames, run the agent</span></span><span class="ck"><svg class="i xs"><use href="#i-check"/></svg></span></button><button class="mi" role="menuitemradio" data-close data-r="Can comment" aria-checked="false"><span>Can comment<span class="d">Leave notes, no edits</span></span><span class="ck"><svg class="i xs"><use href="#i-check"/></svg></span></button><button class="mi" role="menuitemradio" data-close data-r="Can view" aria-checked="false"><span>Can view<span class="d">Read only</span></span><span class="ck"><svg class="i xs"><use href="#i-check"/></svg></span></button></div>
  <div class="ivx-sg"><span class="muted">Suggested</span></div>
  <div class="ivx-mem"></div>
  <div class="ivx-ft"><button class="pill ghost sm ivx-link"><svg class="i xs"><use href="#i-link"/></svg><span>Copy link</span></button><button class="pill primary sm ivx-go" disabled>Send invites</button></div>
</div>
  </Fragment></div>
</div>
<script>
  import './invite-to-collaborate.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Invite ---------- */
/* a sharing panel: the title and what invitees can see, a hairline from edge to edge, the field where addresses become chips
   with the role they get, suggested people, who is in already, and under a second hairline Copy link and Send. Its content is
   16px from every edge in every style, with 16px under each hairline (owner, 18 and 19 Nov); the members' avatars sit on the
   content's left edge and their roles end on its right edge, where the field and Send end. The field's words are 12px in, as
   in every field, and a chip's avatar is clearly inside it, never a near miss of the members' column. The card keeps no room:
   it grows as chips wrap to a new line and as invites go out (grow()), centred in its stage */
.ivx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);max-width:420px;margin:0 auto;width:100%;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
/* (React wraps the card and its role menu in one box, so the menu opens over the card rather than inside it) */
.ivx-w{position:relative;width:100%;max-width:420px;margin:0 auto}
.ivx-h{display:flex;flex-direction:column;font-size:14px;line-height:20px;margin:0 calc(-1 * var(--dm-s-4)) var(--dm-s-1);padding:0 var(--dm-s-4) var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ivx-h b{font-weight:500}
.ivx-h .muted{font-size:12px;line-height:18px}
.ivx-f{display:flex;align-items:flex-start;align-content:center;flex-wrap:wrap;gap:var(--dm-s-1);min-height:var(--dm-field-h);padding:5px 5px 5px var(--dm-s-2);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.ivx-f{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.ivx-f:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.ivx-chips{display:contents}
.ivx-ch{display:inline-flex;align-items:center;gap:6px;height:26px;margin:2px 0;padding:0 var(--dm-s-1) 0 var(--dm-s-1);border-radius:var(--dm-r-tag);background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12.5px;animation:popin .4s var(--dm-ease) backwards}
.ivx-ch .av{width:18px;height:18px;font-size:8.5px}
.ivx-ch.bad{background:var(--dm-bad-bg);color:var(--dm-bad);box-shadow:none}
/* a chip that is not a valid address leads with the warning mark in the avatar's 18px, so every chip's words start on one column */
.ivx-ch.bad>svg{margin:0 3px}
/* chips already on screen keep still when the row is redrawn; only a new one pops in */
.ivx-chips .ivx-ch.seen{animation:none}
.ivx-ch button{display:grid;color:var(--dm-muted)}@media (hover:hover) and (pointer:fine){.ivx-ch button:hover{color:var(--dm-fg)}}
/* on a chip that failed, its remove button is the chip's own red, stepping to full strength under the pointer */
.ivx-ch.bad button{color:color-mix(in srgb,var(--dm-bad) 75%,transparent)}@media (hover:hover) and (pointer:fine){.ivx-ch.bad button:hover{color:var(--dm-bad)}}
.ivx-f input{flex:1;min-width:120px;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;line-height:20px;color:var(--dm-fg);height:30px;padding:0 var(--dm-s-1)}
@supports (corner-shape:squircle){.ivx-ch{corner-shape:squircle;border-radius:var(--dm-r-tag-sq)}}
.ivx-f input::placeholder{color:var(--dm-muted)}
/* the role the invites get: a select at the field's end, in the field's own type so its words share the address's line, and
   its chevron as far in from the field's edge as the address is from the other */
.ivx-role{display:flex;align-items:center;gap:var(--dm-s-1);height:30px;padding:0 var(--dm-s-2);border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13.5px;line-height:20px;color:var(--dm-fg2);margin-left:auto;transition:background-color var(--dm-t-fast)}
.ivx-role[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.ivx-role:hover{background:var(--dm-row)}}
.ivx-sg{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12px}
.ivx-sg .chip .av{width:18px;height:18px;font-size:8.5px;margin-left:-6px}
.ivx-mem{display:flex;flex-direction:column}
.ivx-m{display:flex;align-items:center;gap:var(--dm-s-3);padding:var(--dm-s-1) 0;font-size:13px;line-height:20px}
.ivx-m .av{width:24px;height:24px;font-size:10px}
.ivx-m .t{flex:1;min-width:0;display:flex;flex-direction:column}
.ivx-m .t span{font-size:11.5px;line-height:16px;color:var(--dm-muted)}
.ivx-m .r{font-size:12px;color:var(--dm-muted)}
.ivx-m .r.pend{color:var(--dm-warn)}
/* the buttons sit under a hairline from edge to edge, 16px under it; Copy link's glyph on the content's left edge, its hover
   box reaching out round it, and Send on the right edge */
.ivx-ft{display:flex;justify-content:space-between;align-items:center;gap:6px;margin:0 calc(-1 * var(--dm-s-4)) 0;padding:var(--dm-s-4) var(--dm-s-4) 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ivx-ft .ivx-link{padding:0 var(--dm-s-2);margin-left:calc(-1 * var(--dm-s-2));overflow:hidden;white-space:nowrap}
/* copied: the link's glyph turns into the green tick, the words stay the text colour, and the button eases to its new width */
.ivx-link.copied{color:var(--dm-fg)!important}
@media (hover:hover) and (pointer:fine){.ivx-link.copied:hover{color:var(--dm-fg)!important}}
.ivx-link.copied .i{color:var(--dm-ok-mark)}
.ivx-go[disabled]{box-shadow:none}
@media (hover:hover) and (pointer:fine){.ivx-go[disabled]:hover{box-shadow:none}}
/* Send's words change colour at the same moment its fill does (Clean's ink fill is a gradient, which cannot fade), so it never
   shows white words on the light disabled fill for a moment */
:root[data-style="clean"] .ivx-go,:root [data-style="clean"] .ivx-go,:root [data-style="clean"].ivx-go{transition:transform var(--dm-t-fast) var(--dm-ease)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.ivx :is(.ib,.chip,.ivx-role,.pill):active{transform:none}
/* Clean: Copy link and Send sit in an off-white foot strip, each 8px from the card's edges (28px pills in its 22px corners),
   Copy link the flat secondary button; an address that is not valid keeps the chip's white with its words and mark in red, no
   red fill (owner, 17 Nov) */
/* the role select in the field's corner: its corners the field's less the 5px round it */
:root[data-style="clean"] .ivx-role,:root [data-style="clean"] .ivx-role,:root [data-style="clean"].ivx-role{border-radius:calc(var(--dm-r-field) - 5px)}
:root[data-style="clean"] .ivx-ft,:root [data-style="clean"] .ivx-ft,:root [data-style="clean"].ivx-ft{margin:0 calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4));padding:var(--dm-s-2) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .ivx-ft .ivx-link,:root [data-style="clean"] .ivx-ft .ivx-link,:root [data-style="clean"].ivx-ft .ivx-link{margin-left:0;padding:0 11px;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ivx-ft .ivx-link:hover,:root [data-style="clean"] .ivx-ft .ivx-link:hover,:root [data-style="clean"].ivx-ft .ivx-link:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ivx-ft .ivx-link:active,:root [data-style="clean"] .ivx-ft .ivx-link:active,:root [data-style="clean"].ivx-ft .ivx-link:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .ivx-ch.bad,:root [data-style="clean"] .ivx-ch.bad,:root [data-style="clean"].ivx-ch.bad{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
:root[data-style="clean"] .ivx-ch.bad>svg,:root [data-style="clean"] .ivx-ch.bad>svg,:root [data-style="clean"].ivx-ch.bad>svg{color:var(--dm-bad-mark)}
/* a new chip scales and fades in from where it lands, with no blur */
@keyframes ivxchc{from{opacity:0;transform:scale(.96)}}
:root[data-style="clean"] .ivx-ch,:root [data-style="clean"] .ivx-ch,:root [data-style="clean"].ivx-ch{animation:ivxchc var(--dm-t) var(--dm-ease) backwards}
:root[data-style="clean"] .ivx-chips .ivx-ch.seen,:root [data-style="clean"] .ivx-chips .ivx-ch.seen,:root [data-style="clean"].ivx-chips .ivx-ch.seen{animation:none}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, AV, DM, I, REDUCE, copied, enter, grow, html, swap } from '../core/core.js';
DM.def('invite', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs')).replace(/\{chk\}/g, I('check','xs')).replace('{link}', I('link','xs'));
  const chips = $('.ivx-chips', r), inp = $('.ivx-f input', r), go = $('.ivx-go', r), mem = $('.ivx-mem', r), sg = $('.ivx-sg', r);
  let E = [], role = 'Can edit', shown = new Set();
  const COL = ['var(--dm-av-l)','var(--dm-av-m)','var(--dm-av-t)','var(--dm-av-p)','var(--dm-av-k)'];
  const ok = e => /^\S+@\S+\.\S+$/.test(e);
  const ini = e => e.split('@')[0].slice(0, 2).toUpperCase();
  function paint(){ const seen = shown; shown = new Set(E); chips.innerHTML = E.map((e, i) => `<span class="ivx-ch${ok(e) ? '' : ' bad'}${seen.has(e) ? ' seen' : ''}" ${ok(e) ? '' : 'data-tip="Not a valid email"'}>${ok(e) ? AV(ini(e), COL[i % 5]) : I('alert','xs')}${e}<button aria-label="Remove ${e}">${I('x','xs')}</button></span>`).join('');
    $$('.ivx-ch button', chips).forEach((b, i) => b.onclick = () => { E.splice(i, 1); paint(); });
    const n = E.filter(ok).length; go.disabled = !n || E.some(e => !ok(e)); go.textContent = n > 1 ? `Send ${n} invites` : 'Send invite'; }
  function commit(){ const parts = inp.value.split(/[,\s]+/).map(s => s.trim()).filter(Boolean); if (!parts.length) return; parts.forEach(p => { if (!E.includes(p)) E.push(p); }); inp.value = ''; paint(); }
  inp.onkeydown = e => { if (e.key === 'Enter' || e.key === ',' || e.key === 'Tab'){ if (inp.value.trim()){ e.preventDefault(); commit(); } } else if (e.key === 'Backspace' && !inp.value && E.length){ E.pop(); paint(); } };
  inp.onpaste = () => setTimeout(commit, 0); inp.onblur = commit;
  [['ari@studio.com','AR','var(--dm-av-p)'],['sam@studio.com','SL','var(--dm-av-t)']].forEach(s => { const b = html(`<button class="chip sm">${AV(s[1], s[2])}${s[0].split('@')[0]}</button>`); sg.appendChild(b); b.onclick = () => { if (!E.includes(s[0])){ E.push(s[0]); paint(); } b.remove(); }; });
  $$('.ivx-rp .mi', r).forEach(m => m.addEventListener('click', () => { role = m.dataset.r; $$('.ivx-rp .mi', r).forEach(x => x.setAttribute('aria-checked', x === m)); swap($('.ivx-role span', r), role); }));
  const M = [['MK','var(--dm-av-l)','Maya Kim','Owner'],['JO','var(--dm-av-m)','Jon Ortiz','Can edit']];
  mem.innerHTML = M.map(m => `<div class="ivx-m">${AV(m[0], m[1])}<span class="t">${m[2]}</span><span class="r">${m[3]}</span></div>`).join('');
  // sending: a spinner in place of the words, the button keeping its width so it never goes blank or jumps; then the people
  // invited join the list as pending, one after another
  go.onclick = () => c.run(async () => { go.style.width = go.getBoundingClientRect().width + 'px'; go.innerHTML = '<span class="spin"></span>'; await c.wait(800); go.style.width = ''; E.filter(ok).forEach((e, i) => { const el = html(`<div class="ivx-m">${AV(ini(e), COL[i % 5])}<span class="t">${e.split('@')[0]}<span>${e}</span></span><span class="r pend">Invited, ${role.toLowerCase()}</span></div>`); mem.appendChild(el); enter(el, i * 70); }); E = []; paint(); });
  // Copy link: its glyph turns into the green tick and its words into Link copied, the button easing to its new width with no
  // room kept for the longer words (owner, 19 Nov), then it all goes back
  const lk = $('.ivx-link', r), lb = $('span', lk) || lk;
  const words = t => { const w0 = lk.getBoundingClientRect().width; lb.textContent = t; const w1 = lk.getBoundingClientRect().width;
    if (!REDUCE && Math.abs(w1 - w0) > .5){ const cs = getComputedStyle(lk), d = parseFloat(cs.getPropertyValue('--dm-t')) || .34; lk.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(d < 10 ? d * 1000 : d), easing:cs.getPropertyValue('--dm-ease').trim() || 'ease' }); } };
  lk.onclick = () => { copied(lk, 'https://designme.dev/join/pricing-refresh'); words('Link copied'); clearTimeout(lk._lt); lk._lt = setTimeout(() => words('Copy link'), 1600); };
  paint();
  // the card keeps no room for a later state: it grows as chips wrap to a new line and as invites go out, centred in its
  // stage (grow(), once its entrance has ended). Its role menu opens from the stage, over the card, so the card's clip never
  // cuts it
  const root = r.classList.contains('ivx') ? r : $('.ivx', r), rp = $('.ivx-rp', r);
  if (root && rp && root.contains(rp) && root !== r) r.appendChild(rp);
  if (root) Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  // the preview adds two people on its own; clicking, focusing or typing in it takes over, and what it had typed goes
  c.auto(900, () => c.run(async () => { await c.type(inp, 'dana@studio.com', { keep:true }); await c.step(40); commit(); await c.type(inp, ' lee@studio', { keep:true }); commit(); }));
});
